export const source = '유럽 쪽은 Natural Earth 1:10m admin-1(v5.1.2) 현대 행정구역 조각을 그 시기 국경에 맞춰 묶고, 조각이 역사 경계와 다른 곳은 선을 그어 나눈 근사. 유럽 밖(시베리아·중앙아시아·극동)은 대략적인 추정. 운영자 검수 필요';

// ── 행정구역 조각 ─────────────────────────────────────────
const EU = loadFragments('europe');
const { F, domain } = EU;

// adm0(Natural Earth 나라 코드)별 조각 id
const idsOf = (...adm0s) => EU.ids.filter((id) => adm0s.includes(EU.props.get(id).adm0));
// ids에서 빼기. 빼려는 id가 목록에 없으면 멈춘다(조각 id 오타를 잡는다)
const minus = (ids, ...out) => {
  for (const id of out) if (!ids.includes(id)) throw new Error(`europe.mjs: 빼려는 조각 ${id}가 목록에 없음`);
  return ids.filter((id) => !out.includes(id));
};
// 아라스강 남쪽 이란 북서부(아제르바이잔·나흐치반·아르메니아 남쪽): 권역 바깥선 밖의 이 땅은 모두 이란(카자르)이다. 러시아 손 도형의 남쪽 변
