// 조각으로 바꾼 아제르바이잔 국경과 맞닿게 잘라 낸다 (2026-10-01, 접합부 쐐기). 권역 바깥선 안쪽은 조각이 정하므로 상자가 그쪽을 덮어도 상관없다
