// ── 1918~1945 조각 소유표 (작업 B1) ─────────────────────────────
// 1차 대전 뒤(1918년 말)부터 2차 대전 종전 직후(1945년 말)까지. 버전은 그해 말 모습이다.
// 1918년 말은 강화 조약 전의 과도기다. E3의 1814년처럼, 무너진 오스트리아-헝가리·러시아 제국 땅은 새로 선 나라가 대개 실제로 다스린 쪽(뒤의 조약 배분과 같음)으로 둔다:
// 오스트리아·헝가리·체코슬로바키아·세르브-크로아트-슬로벤 왕국·폴란드(동쪽은 1921년 리가 조약 경계)·대루마니아·이탈리아(남티롤·율리안 마치)는 1918년부터.
// 독일은 1918년까지 1914년 국경(법적 국경), 베르사유 조약(1919년 6월 서명)의 포젠·서프로이센·알자스-로렌은 1919년, 1920년에 넘어간 단치히·메멜·자르·북슐레스비히·오이펜-말메디는 1920년.
// 다르게 둔 곳(근사): 카르파티아 루스는 1918년부터 체코슬로바키아(1919년 초 장악), 동갈리치아는 1918년부터 폴란드(1919년 7월까지 서우크라이나 인민 공화국과 전쟁),
// 빌뉴스 지방은 1918년 리투아니아·1919년부터 폴란드(1920~1922 중부 리투아니아 공화국도 폴란드로), 헝가리 남부 바라냐(페치, 1921년까지 세르비아군 점령)는 헝가리,
// 서트라키아는 1919년부터 그리스(1920년 5월까지 연합국 관리), 카르스·아르다한(1918~1920 아르메니아 공화국)은 1920년까지 소련 쪽, 우크라이나·캅카스의 내전기 나라들(1918~1921)은 소련에 넣음.
// 2차 대전(1939~1945)은 그해 말 모습이다. 독일이 법령으로 병합하거나 민정장관을 두어 사실상 병합한 곳(오스트리아·주데텐·메멜·단치히·폴란드 서부·수바우키·오이펜-말메디·알자스-로렌·룩셈부르크·북슬로베니아)은
// 독일 땅으로, 나머지 점령지는 나라 영토 위의 점령 항목(occupied_by): 보헤미아-모라비아 보호령, 폴란드 총독부, 독일 점령 프랑스 북부, 이탈리아 점령 프랑스 남동부(1942),
// 독일 점령 소련(발트 3국·서벨라루스·서우크라이나 포함, 루마니아의 트란스니스트리아와 비아위스토크 지구도 이 항목에 묶음), 핀란드 점령 동카렐리야, 독일 점령 세르비아, 몬테네그로 점령지(이탈리아, 1943년부터 독일),
// 독일 점령 이탈리아 북부(1943~1944). 나라 전체가 점령되고 정부가 남은 덴마크·노르웨이·네덜란드·벨기에·그리스·알바니아·헝가리(1944)·슬로바키아(1944)와 비시 프랑스(1942~1943)는
// 영토를 그대로 두고 relations.yaml에 occupied_by를 단다. 위성국(슬로바키아·크로아티아 독립국)은 따로 항목에 vassal_of.
// 1945년 말: 독일은 4개 점령 지구와 베를린(동·서), 오데르-나이세선 동쪽은 폴란드, 쾨니히스베르크 쪽은 소련, 오스트리아는 공화국(4개국 점령은 지도에 나누지 않고 relations.yaml에 occupied_by 넷), 율리안 마치·도데카니사는
// 1947년 파리 강화 조약 전이라 이탈리아(법적 국경. 유고슬라비아·영국 군정은 나누지 않음).
// 이름만 바뀐 해(renames): 바이마르 공화국 → 나치 독일(1933), 오스만 제국 → 튀르키예(1923).
// 쪼개지 않은 근사(각 1만 km² 미만): 자오제·흘루친(체코)·오라바·스피시, 차리브로드·보실레그라드(이미 세르비아로 둠), 1915년 마리차강 동쪽 띠(불가리아),
// 자다르·크레스·로시니·라스토보(1920~1947 이탈리아), 이탈리아령 달마티아(1941~1943)와 코토르만(1941~1943 이탈리아, 몬테네그로 점령지에 묶음), 크로아티아 바라냐(1941~1944 헝가리, 크로아티아 독립국으로 둠),
// 코소보 북부(독일)·동부(불가리아) 점령지(1941~1944, 알바니아로 묶음), 그리스의 독일·이탈리아 점령 구역 구분과 에브로스(독일 점령, 불가리아로 묶음), 1938년 자오제(폴란드)·1939년 슬로바키아 동부 띠(헝가리),
// 1940~1941 한코반도 조차지·1944~1956 포르칼라 조차지(소련), 1940~1943 망통(이탈리아), 채널 제도(1940~1945 독일 점령), 1939년 슬로바키아에 넘어간 오라바·스피시 일부,
// 피우메 1918~1919(연합국 공동 점령, 1919년 9월부터 단눈치오 점령)는 이탈리아로 둠, 1941년 말 세바스토폴·케르치(소련)와 1944년 말 메멜 시·동프로이센 동부·헝가리 동부·슬로바키아 동부의 소련군 점령, 1944년 말 남네덜란드·핀마르크 해방, 1943년 10월 코르시카 해방,
// 1944~1945 콜마르 포켓, 바르샤바 북쪽 나레프강 교두보, 1945년 율리안 마치의 유고슬라비아 군정(B 지구)
// 이 표의 블록 안에서 나눈 조각·조각 목록 가운데 '1946~1991 조각 소유표'(작업 B2)가 reuse로 같은 단위를 이어 쓰는 것(블록 끝에서 채움).
