  own(whole(...idsOf('ALB')), [[1918, AL]]);
  // 그리스: 1919년 서트라키아(뇌이 조약), 1919~1922 스미르나(이즈미르) 점령과 1920~1922 동트라키아(세브르 조약), 그리스-튀르키예 전쟁에 져 로잔 조약(1923)으로 돌려줌.
  // 1941년 4월 독일·이탈리아·불가리아 점령(동마케도니아·서트라키아는 불가리아가 병합), 1944년 10월 해방
