  // 불가리아: 1919년 뇌이 조약으로 서트라키아·스트루미차를 잃음, 1940년 남도브루자. 1941~1944 마케도니아·서트라키아(위)
  own(whole(...BG_PRINCIPALITY, ...BG_RUMELIA, 'BG-01', 'BG-09', 'BG-21'), [[1918, BG]]);
