  // 그리스 점령(1919~1922): 1919년 이즈미르·마니사, 1920년 아이딘·발르케시르·부르사·우샤크·차나칼레(비가반도·갈리폴리반도, 해협 지대는 연합국 관리)와 동트라키아, 1921년 퀴타히아·에스키셰히르·아피온·빌레지크(사카리아 전투 뒤의 전선)
