// 표가 바뀌는 해에 단위 이름만 바뀌고 땅은 같은 이음매: 앞 버전의 단위 목록으로 잇는다(작업 B1).
// 프랑스는 1918년 표에서 1940년 분계선이 지나는 도를 나눈 단위로 쓰지만 1917년과 땅이 같다(대칭차 0km²)
const SAME_LAND_SEAMS = { france: [1918] };
for (const [id, years] of Object.entries(SAME_LAND_SEAMS)) {
  for (const y of years) {
    const segs = segments[id];
    const i = segs.findIndex(([from]) => from === y);
    if (i < 1 || segs[i - 1][1] !== y) throw new Error(`europe.mjs: ${id}의 ${y}년 이음매가 없음`);
    segs.splice(i - 1, 2, [segs[i - 1][0], segs[i][1], segs[i - 1][2]]);
  }
}
const tableVersions = (id) => {
  const segs = segments[id];
  if (!segs) throw new Error(`europe.mjs: 소유표에 ${id}의 땅이 없음`);
  const reaches = segs.at(-1)[1] === TABLE_TO;
  if (reaches !== Object.hasOwn(TAIL_TO, id)) throw new Error(`europe.mjs: ${id}의 TAIL_TO가 ${reaches ? '없음' : '필요 없음'}`);
  return segs.map(([from, to, list]) => [from, to === TABLE_TO ? TAIL_TO[id] : to, list]);
};

